package com.huy.enterprise.inventory;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/warehouses") @RequiredArgsConstructor public class WarehouseController{private final WarehouseService service;@GetMapping public List<WarehouseResponse> all(){return service.all();}@GetMapping("/{id}") public WarehouseResponse one(@PathVariable UUID id){return service.one(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public WarehouseResponse create(@Valid @RequestBody WarehouseRequest r){return service.create(r);}@PutMapping("/{id}") public WarehouseResponse update(@PathVariable UUID id,@Valid @RequestBody WarehouseRequest r){return service.update(id,r);}}
